function registerSlingApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "DELETE", path_prefix * "/etc/replication/agents.{runmode}/{name}", OpenAPI.Servers.middleware(impl, delete_agent_read, delete_agent_validate, delete_agent_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/{path}/{name}", OpenAPI.Servers.middleware(impl, delete_node_read, delete_node_validate, delete_node_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/etc/replication/agents.{runmode}/{name}", OpenAPI.Servers.middleware(impl, get_agent_read, get_agent_validate, get_agent_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/etc/replication/agents.{runmode}.-1.json", OpenAPI.Servers.middleware(impl, get_agents_read, get_agents_validate, get_agents_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/{intermediatePath}/{authorizableId}.ks.json", OpenAPI.Servers.middleware(impl, get_authorizable_keystore_read, get_authorizable_keystore_validate, get_authorizable_keystore_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/{intermediatePath}/{authorizableId}/keystore/store.p12", OpenAPI.Servers.middleware(impl, get_keystore_read, get_keystore_validate, get_keystore_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/{path}/{name}", OpenAPI.Servers.middleware(impl, get_node_read, get_node_validate, get_node_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/etc/packages/{group}/{name}-{version}.zip", OpenAPI.Servers.middleware(impl, get_package_read, get_package_validate, get_package_invoke; optional_middlewares...))
